package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import com.google.gson.*;
/** Authored R03 keys, parsed once; deployment can pause/reverse at any saved pose. */
final class Mpl01Animation {
 private record Key(float time,float x,float y,float z){}private static final Map<String,Map<String,List<Key>>> CLIP=load();
 private static Map<String,Map<String,List<Key>>> load(){try(var in=Mpl01Animation.class.getResourceAsStream("/assets/sbwdroneconfig/animations/mobile_patriot_launcher_mpl01.animation.json")){var root=JsonParser.parseReader(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonObject("animations").getAsJsonObject("animation.mpl01.r03_deploy").getAsJsonObject("bones");Map<String,Map<String,List<Key>>> out=new LinkedHashMap<>();for(var bone:root.entrySet()){var channels=new LinkedHashMap<String,List<Key>>();for(var c:bone.getValue().getAsJsonObject().entrySet()){var keys=new ArrayList<Key>();for(var k:c.getValue().getAsJsonObject().entrySet()){var a=k.getValue().getAsJsonArray();keys.add(new Key(Float.parseFloat(k.getKey()),a.get(0).getAsFloat(),a.get(1).getAsFloat(),a.get(2).getAsFloat()));}keys.sort(Comparator.comparingDouble(Key::time));channels.put(c.getKey(),List.copyOf(keys));}out.put(bone.getKey(),channels);}return out;}catch(Exception e){throw new IllegalStateException("Missing authored MPL-01 deployment animation",e);}}
 static void apply(Mpl01Model model,float time){for(var entry:CLIP.entrySet())model.getBone(entry.getKey()).ifPresent(b->{float sampleTime=entry.getKey().startsWith("Jack_")?(time<1?0:Math.min(1,time-.5f)):(entry.getKey().equals("Launcher_Pitch")||entry.getKey().startsWith("Lift_"))?(time<=1.5f?0:1+(time-1.5f)*3/2.5f):time;for(var channel:entry.getValue().entrySet()){var keys=channel.getValue();Key a=keys.get(0),z=keys.get(keys.size()-1);for(int i=1;i<keys.size();i++)if(keys.get(i).time>=sampleTime){a=keys.get(i-1);z=keys.get(i);break;}float f=z.time==a.time?0:Math.max(0,Math.min(1,(sampleTime-a.time)/(z.time-a.time))),x=a.x+(z.x-a.x)*f,y=a.y+(z.y-a.y)*f,v=a.z+(z.z-a.z)*f;switch(channel.getKey()){case"rotation"->{b.setRotX(x*.017453293f);b.setRotY(y*.017453293f);b.setRotZ(v*.017453293f);}case"position"->{b.setPosX(x);b.setPosY(y);b.setPosZ(v);}case"scale"->{b.setScaleX(x);b.setScaleY(y);b.setScaleZ(v);}}}});}
 private Mpl01Animation(){}
}
